namespace Heimora;

internal sealed record HelpTopic(string Category, string Title, string Body, string Keywords = "");
internal static class HelpTopics
{
    public static readonly IReadOnlyList<HelpTopic> All =
    [
        new("Over Heimora", "De naam Heimora: Heimdall en aurora", "Heimora is onze eigen samengestelde merknaam, geïnspireerd op Heimdall en aurora. Het is geen historische Noorse naam en geen letterlijke vertaling. We combineerden het idee van een waakzame bewaker met het vloeiende licht van het poollicht.\n\nHeimdall\nIn de Noorse mythologie is Heimdall een waakzame god die de wacht houdt bij Bifröst: de regenboogbrug tussen Asgard en de mensenwereld. Hij staat in ons merkverhaal voor bewaken, toegang en zorgvuldig omgaan met verbindingen. Dit is een symbolische inspiratie, geen technische beveiligingsgarantie.\n\nAurora\nAurora verwijst hier naar poollicht: het noorderlicht (aurora borealis) en zuiderlicht (aurora australis). Deze lichtverschijnselen hangen samen met geladen deeltjes, het aardmagnetisch veld en de atmosfeer. De vloeiende lichtbanden vormen de inspiratie voor het logo en het auroragroene accent.\n\nNaam en ontwerp\nHeimdall leverde de inspiratie voor Heim-, aurora voor de vloeiende klank en het lichtmotief. Het logo combineert een beschermende poort met twee aurorabanden. Middernachtblauw (#101B2D) geeft rust, auroragroen (#19C9B0) vormt het merkaccent, helderblauw (#397CF6) markeert acties en ijsgrijs (#F4F7FB) houdt de werkruimte licht.\n\nBronnen voor de achtergrond: het Zweedse Historiska museet (Heimdall) en NASA Science (aurora). De volledige bronlinks en kleuren staan in NAME-AND-BRANDING.md bij de applicatie.", "heimora naam oorsprong betekenis heimdall aurora bifrost mythologie poollicht logo kleuren branding"),
        new("Beveiliging", "Nieuw of gewijzigd verbindingsdoel bevestigen", "Voor een RDP- of SSH-verbinding controleert de app of dit doel op deze pc al is goedgekeurd. Een nieuwe of gewijzigde server, poort, protocol, eigen loginidentiteit of credentialkoppeling vraagt eerst om bevestiging. Standaard is Nee geselecteerd. Pas na toestemming haalt de app de verbindingscredentials op.\n\nControleer het doel ook als iemand anders verbindingsmetadata in PostgreSQL kan wijzigen. De lokale goedkeuring wordt versleuteld opgeslagen. Dit vervangt geen RDP-certificaatcontrole of SSH-hostkeycontrole en detecteert geen DNS-kaping op zichzelf.", "bestemming server goedkeuring vertrouwen trust host credential lek database"),
        new("Verbindingen en accounts", "Webpagina’s opslaan en openen", "Kies Start → Nieuwe webpagina. Vul een naam, map en volledige URL in, bijvoorbeeld https://portal.example.nl. Dubbelklik op het item of kies Verbinden om het in je standaardbrowser te openen. Bewerken en verwijderen werken zoals bij andere items. Zoeken vindt ook URL’s.\n\nOndersteund zijn http:// en https://. Adressen met gebruikersnaam of wachtwoord en andere schema’s worden geweigerd. Sla geen toegangstokens op in de URL. De website verzorgt de aanmelding; de app vult hier geen credentials automatisch in.\n\nWebpagina’s worden in dezelfde kluis bewaard en gaan mee met de metadata-migratie naar PostgreSQL. Het openen van de browser wordt gelogd; dit bewijst niet dat de pagina bereikbaar is.", "web browser URL website intranet portaal http https"),
        new("Aan de slag", "Welkom en eerste stappen", "Heimora brengt RDP, SSH en herbruikbare credentials samen in één werkplek.\n\n1. Maak met + Map een mappenstructuur.\n2. Voeg met + Verbinding een RDP- of SSH-verbinding toe.\n3. Vul naam, hostnaam/IP en poort in.\n4. Kies eigen inloggegevens of een opgeslagen credential.\n5. Dubbelklik op de verbinding om een sessietab te openen.\n\nHet overzicht toont de werkelijke aantallen opgeslagen verbindingen, credentials en mappen. Deze aantallen betekenen niet dat systemen online zijn. De app start met de lokale kluis. Je kunt daarna PostgreSQL openen.", "start handleiding dashboard overzicht"),
        new("Aan de slag", "Mappen en zoeken", "Maak mappen via Start → Nieuwe map of + Map. Mappen mogen onder elkaar staan en hebben een eigen kleur. In een item-editor kies je bij Map waar het item hoort; zo verplaats je een verbinding of credential.\n\nHet zoekveld links zoekt op itemnaam, hostnaam en IP-adres. Bovenliggende mappen blijven zichtbaar. Zoek bij credentials op de zelfgekozen naam; de versleutelde inloggegevens worden niet doorzocht.\n\nVia Beeld kun je mappen uitvouwen/invouwen en het navigatiepaneel of de statusbalk tonen/verbergen.", "folder tree navigatie verplaatsen kleur filter"),
        new("Verbindingen en accounts", "RDP en SSH gebruiken", "Een RDP-verbinding gebruikt standaard poort 3389; SSH gebruikt standaard 22. Kies het juiste protocol, hostadres en de juiste poort.\n\nVoor RDP kun je een gebruikersnaam en eventueel een domein instellen. Klembord delen is een aparte RDP-optie; schijfomleiding staat uit. RDP gebruikt de Windows-clientcomponent met NLA/CredSSP.\n\nSSH gebruikt de meegeleverde PuTTY-terminal. Controleer bij een nieuwe host de servervingerafdruk via een onafhankelijke bron voordat je de host vertrouwt. Controleer ook RDP-certificaatwaarschuwingen.\n\nEen tab sluit je met het kruisje, de werkbalk, middelklik of Ctrl+W. Binnen een remote sessie kunnen toetsen naar het remote systeem gaan. Een geopende client is geen bewijs van een geslaagde aanmelding.", "remote desktop terminal certificaat hostkey fingerprint sessie poort"),
        new("Verbindingen en accounts", "Credentials maken en koppelen", "Maak een credential via + Credential of Start → Nieuwe credential. Geef een duidelijke naam, kies een map en vul gebruikersnaam, eventueel domein en wachtwoord in. Het item krijgt een sleutelpictogram. Dubbelklik op het item om het te bewerken.\n\nBij een verbinding kies je onder Inloggegevens:\n• Eigen inloggegevens: deze verbinding gebruikt zijn eigen velden.\n• Koppelen aan credential: kies een credential uit de lijst.\n\nMeerdere verbindingen kunnen één credential gebruiken. Bij opnieuw verbinden gebruiken ze de actuele gegevens. Een wijziging in de app verandert het wachtwoord op de server zelf niet.\n\nBij wisselen naar een koppeling blijven eerdere eigen gegevens bewaard voor terugschakelen. Een ontbrekende gekoppelde credential wordt niet stilzwijgend vervangen door die eigen gegevens. Een credential die nog in gebruik is kan niet worden verwijderd.", "account password gebruikersnaam domein eigen custom hergebruik wijzigen verwijderen"),
        new("Gegevensbronnen", "PostgreSQL aansluiten", "Maak op je eigen server een aparte database en databasegebruiker. Open PostgreSQL via de werkbalk of Bestand. Vul server, poort, database en databasegebruiker in. De app maakt alleen haar eigen tabel aan; de database zelf moet al bestaan. Gebruik geen superuser.\n\nStandaard controleert de app het TLS-servercertificaat én de servernaam. Bij een eigen CA kun je een CA-certificaatbestand kiezen. TLS uitschakelen is alleen een expliciete laboptie; gebruik dit niet in productie. De gekozen TLS-modus wordt in het auditspoor opgenomen.\n\nPostgreSQL bevat verbindingsmetadata, credentialnamen en koppelingen. Credential-gebruikersnamen, domeinen en wachtwoorden blijven lokaal versleuteld. Op een andere pc vul je ze opnieuw lokaal in.\n\nBij een lege PostgreSQL-kluis biedt de app migratie aan: mappen, verbindingen en credentialkoppelingen worden na bevestiging overgenomen. De app maakt eerst een beveiligde lokale databasekopie, behoudt de ID’s en controleert de teruggelezen inhoud. Je lokale bron blijft behouden. Een gevulde doelkluis wordt niet automatisch overschreven of samengevoegd. Er is geen offline synchronisatie. Vernieuwen laadt de actieve kluis opnieuw. Bij gelijktijdige databasewijzigingen wordt overschrijven geweigerd.", "postgres postgresq database SSL TLS CA verifyfull netwerk synchronisatie"),
        new("Uiterlijk", "Branding, kleuren en splashscherm", "Open Beheer → Instellingen en branding of klik op Instellingen. Je kunt de zichtbare appnaam, hoofdkleur, accentkleur en een eigen logo aanpassen. De voorbeeldweergave verandert direct; Opslaan past de instellingen toe. Annuleren bewaart de bestaande instellingen.\n\nLogo's: PNG, JPG of BMP, maximaal 2 MB en 4096 × 4096 pixels. Het logo wordt verkleind en lokaal opgeslagen, zodat het oorspronkelijke bestand later niet nodig is. De Windows-productnaam blijft Heimora.\n\nHet splashscherm gebruikt dezelfde branding. Het toont de opstartfase en sluit zodra de werkplek is geladen. Het splashscherm blijft minimaal vijf seconden staan terwijl de app laadt. Bij langer laden blijft het zichtbaar tot de werkplek gereed is. Instellingen gelden per Windows-account op deze pc.", "logo naam kleur thema uiterlijk laden splash instellingen"),
        new("Beveiliging", "Hoe opgeslagen wachtwoorden worden beschermd", "De lokale SQLite-database bewaart de inhoud van mappen, verbindingen en credentials in Windows-DPAPI-versleutelde records voor het huidige Windows-account. De database-engine zit in de installer. Er staat geen vaste decryptiesleutel in de app. Wachtwoorden worden versleuteld opgeslagen, niet alleen gehasht: de app moet ze immers kunnen opvragen en gebruiken.\n\nBij herbruikbare credentials worden gebruikersnaam, domein en wachtwoord samen versleuteld. Eigen gebruikersnaam/domein van een verbinding staan in de metadata; eigen wachtwoorden zijn versleuteld. Naam en map van een credential zijn metadata.\n\nOpslagformaat 2 bindt versleutelde waarden aan hun item-ID en audit-identiteit. Bestandsrechten beperken de beveiligde opslag tot het huidige Windows-account en SYSTEM. Back-ups met wachtwoorden blijven versleuteld.\n\nBelangrijke grens: dit is geen aparte app-ontgrendeling. Malware onder jouw Windows-account, een overgenomen ontgrendelde sessie of een beheerder kan de lokale bescherming omzeilen. Sterke Windows-beveiliging blijft nodig. De app maakt een zwak wachtwoord op een doelsysteem niet vanzelf sterk.", "DPAPI encryptie versleuteling veiligheid kraken hash entropy opslag data privacy"),
        new("Beveiliging", "Wachtwoord opvragen en aanpassen", "Open de verbinding of credential met Bewerken. Wachtwoorden zijn standaard gemaskeerd. Met Wachtwoord tonen worden ze tijdelijk zichtbaar.\n\nTonen wordt vooraf in het auditlog vastgelegd. Na 15 seconden of bij het verlaten van het venster maskeert de app het veld opnieuw. Als auditregistratie niet beschikbaar is, wordt het wachtwoord niet getoond.\n\nJe kunt een wachtwoord wijzigen en opslaan. Plakken en selecteren blijven mogelijk; kopiëren/knippen via het wachtwoordveld is uitgeschakeld om nieuwe clipboardkopieën te beperken. Een leeg wachtwoord kan worden gebruikt voor een clientprompt of andere clientauthenticatie.\n\nInloggegevens zijn tijdens noodzakelijk gebruik aanwezig in app-/clientgeheugen. Deze versie gebruikt geen extra appwachtwoord, Windows-Hello-controle of MFA bij het tonen.", "tonen lezen reveal bewerken wijzigen kopiëren plakken masker timer wachtwoord"),
        new("Beveiliging", "Auditlog: wie deed wat en wanneer?", "Open Beheer → Auditlog. Het venster is alleen-lezen en toont Windows-gebruiker, werkstation, UTC-tijd, actie, resultaat en itemreferentie.\n\nGeregistreerd worden onder meer het opvragen, tonen, toevoegen, wijzigen en verwijderen van inloggegevens, itemwijzigingen, openen van de verbindingsclient en openen van de database. Wachtwoordvelden staan niet in dit log. Geslaagd bij een verbindingsclient betekent dat de client is geopend; het bewijst geen geslaagde remote aanmelding.\n\nEen HMAC-controleketen en beveiligd controlepunt helpen wijzigingen, inkorten en ontbrekende bestanden detecteren. Bij een ongeldige of onbeschrijfbare auditvoorziening wordt wachtwoordtoegang geblokkeerd. Een Gestart-record zonder afloop kan wijzen op een onderbroken bewerking.\n\nDit is een lokaal log, geen onafhankelijk serverbewijs. De actor is het Windows-account en de tijd komt van deze pc. Terugzetten van een oud log met een bijpassend oud controlepunt kan niet betrouwbaar lokaal worden gedetecteerd. Voor productie met meerdere gebruikers is centrale authenticatie en onafhankelijke auditopslag nodig.", "audit logging logboek historie Windows SID HMAC integriteit gebruiker UTC gebeurtenissen"),
        new("Herstel en beheer", "Back-ups en veilig herstellen", "Sluit de app voordat je een gewone bestandskopie van de gegevensmap maakt. De actieve gegevensmap staat in:\n\n%LOCALAPPDATA%\\Heimora\n\nMaak een back-up van de hele map. Sinds versie 0.5 horen heimora.db en de map security bij elkaar. Alleen het wachtwoordbestand of alleen een auditbestand terugzetten is geen ondersteunde herstelroute. Bewaar ook je verbindingsmetadata en instellingen.\n\nDe eerste start van 0.5 zet oudere JSON-opslag om naar een SQLite-database met versleutelde records. Pas na succesvolle opslag worden oude bestanden en back-ups versleuteld gearchiveerd. De SQLite-header en het schema blijven zichtbaar; dit is geen SQLCipher. Oudere appversies kunnen het nieuwe formaat niet lezen.\n\nAls de beveiligde auditstatus of het log ontbreekt of beschadigd is, verwijder die bestanden dan niet om de controle te omzeilen. Bewaar de bestaande bestanden en herstel een complete, bijbehorende back-up. Een andere pc kan de gegevens niet automatisch ontsleutelen: de Windows-DPAPI-context moet ook beschikbaar zijn.\n\nDeze hulp kan apart vanuit het startmenu worden geopend, ook als de normale app niet start.", "backup back-up recovery restore auditlog beschadigd ontbreekt migratie fout secrets herstel"),
        new("Herstel en beheer", "Gebruikers, rechten en productie", "Deze versie gebruikt je Windows-account. Er zijn nog geen afzonderlijke appgebruikers, beheerdersaccounts, rollen of centrale wachtwoordkluis. Installeren met Windows-beheerdersrechten maakt geen appbeheerder aan. De dagelijkse app draait zonder verplichte elevatie.\n\nEen gedeelde databasegebruiker is geen vervanging voor individuele applicatierechten. Voor productie met meerdere personen is een centrale service vóór PostgreSQL nodig, met eigen authenticatie/rechten en een auditbestemming buiten de controle van de desktopgebruiker.\n\nDit is een preview. Lokale beveiligings- en regressietests zijn uitgevoerd, maar echte RDP-/SSH-aanmeldingen, live PostgreSQL, volledig installatie-/update-/hersteltesten op een schone pc en onafhankelijke beoordeling blijven nodig. De installer is nog niet digitaal ondertekend.\n\nHet meegeleverde SECURITY-REVIEW.md beschrijft de uitgevoerde broncodecontrole en resterende grenzen.", "admin beheerder login rechten rollen MFA productie pentest signing certificering"),
        new("Herstel en beheer", "Problemen met starten of verbinden", "Start de app niet twee keer met dezelfde gegevensmap. Sluit een bestaande instantie eerst, ook als die in een andere Windows-sessie draait.\n\nBij een credentialmelding: controleer de koppeling en vul de credential op deze pc lokaal in. Bij PostgreSQL: controleer bereikbaarheid, poort, database, rechten, servernaam en CA-certificaat. Bij gelijktijdige wijzigingen: vernieuw de kluis en voer de wijziging opnieuw uit.\n\nBij een geweigerde SSH-client: installeer de originele applicatie opnieuw. De app controleert de meegeleverde client vóór wachtwoordoverdracht. Vervang die executable niet zelf door een andere versie.\n\nBij auditproblemen: volg Back-ups en veilig herstellen. De app blokkeert toegang bewust wanneer logging niet betrouwbaar werkt.\n\nWerkt de normale start niet? Open Handleiding en beveiliging vanuit de appgroep in het startmenu. De hulpfunctie opent geen wachtwoordopslag.", "foutmelding crash opstarten dubbel netwerk host timeout geblokkeerd"),
        new("Aan de slag", "Sneltoetsen", "F1 — Helpcentrum\nCtrl+N — Nieuwe verbinding\nCtrl+Shift+N — Nieuwe map\nF2 — Bewerken\nF5 — Vernieuwen\nCtrl+W — Sessietab sluiten\nCtrl+, — Instellingen\n\nBinnen een remote sessie kunnen toetsen naar het remote systeem gaan. Gebruik dan de werkbalk of het kruisje op de tab.", "keyboard toetsen shortcuts toetsenbord")
    ];
    public static IReadOnlyList<HelpTopic> Search(string query)
    {
        var terms = query.Split((char[]?)null, StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries);
        return All.Where(x => terms.All(t => (x.Title + " " + x.Category + " " + x.Body + " " + x.Keywords).Contains(t, StringComparison.OrdinalIgnoreCase))).ToList();
    }
}

internal sealed class HelpCenter : LocalizedForm
{
    private readonly TextBox search = new() { Name = "HelpSearch", Dock = DockStyle.Top, PlaceholderText = "Zoeken in alle onderwerpen…", BorderStyle = BorderStyle.FixedSingle };
    private readonly TreeView topics = new() { Name = "HelpTopics", Dock = DockStyle.Fill, BorderStyle = BorderStyle.None, HideSelection = false, ItemHeight = 28, ShowNodeToolTips = true };
    private readonly RichTextBox article = new() { Name = "HelpArticle", Dock = DockStyle.Fill, ReadOnly = true, BorderStyle = BorderStyle.None, BackColor = Color.White, Font = new Font("Segoe UI", 11), DetectUrls = false };
    private readonly Label title = new() { Dock = DockStyle.Top, Height = 65, Font = new Font("Segoe UI Semibold", 19), Padding = new Padding(0, 15, 0, 0), AutoEllipsis = true };
    private readonly Label result = new() { Dock = DockStyle.Bottom, Height = 32, ForeColor = Color.DimGray };
    public HelpCenter()
    {
        Text = "Helpcentrum - Heimora"; Font = new Font("Segoe UI", 10); Size = new Size(1180, 800); MinimumSize = new Size(900, 600); StartPosition = FormStartPosition.CenterParent;
        BackColor = Color.FromArgb(244, 247, 251); Icon = Icon.ExtractAssociatedIcon(Application.ExecutablePath);
        var heading = new Label { Text = "Handleiding & beveiliging", Font = new Font("Segoe UI Semibold", 21), ForeColor = Color.White, BackColor = Color.FromArgb(16, 27, 45), Dock = DockStyle.Top, Height = 78, Padding = new Padding(23, 19, 0, 0) };
        var split = new SplitContainer { Dock = DockStyle.Fill, Size = new Size(1100, 600), SplitterDistance = 320, SplitterWidth = 5 };
        var left = new Panel { Dock = DockStyle.Fill, BackColor = Color.White, Padding = new Padding(16) };
        var searchBox = new Panel { Dock = DockStyle.Top, Height = 45 }; searchBox.Controls.Add(search);
        left.Controls.Add(topics); left.Controls.Add(result); left.Controls.Add(searchBox); split.Panel1.Controls.Add(left);
        var right = new Panel { Dock = DockStyle.Fill, Padding = new Padding(28, 5, 28, 20), BackColor = Color.White }; right.Controls.Add(article); right.Controls.Add(title); split.Panel2.Controls.Add(right);
        Controls.Add(split); Controls.Add(heading);
        topics.AfterSelect += (_, e) => { if (e.Node?.Tag is HelpTopic topic) { title.Text = topic.Title; article.Text = topic.Body; article.SelectionStart = 0; article.ScrollToCaret(); } };
        search.TextChanged += (_, _) => Filter(); Filter();
    }
    private void Filter()
    {
        var matches = HelpTopics.Search(search.Text); topics.BeginUpdate(); topics.Nodes.Clear(); TreeNode? first = null;
        foreach (var group in matches.GroupBy(x => x.Category))
        {
            var category = topics.Nodes.Add(group.Key); category.ForeColor = Color.FromArgb(90, 107, 128);
            foreach (var topic in group) { var node = new TreeNode(topic.Title) { Tag = topic, ToolTipText = topic.Title }; category.Nodes.Add(node); first ??= node; }
            category.Expand();
        }
        topics.EndUpdate(); result.Text = $"{matches.Count} onderwerpen · offline beschikbaar";
        if (first != null) topics.SelectedNode = first;
        else { title.Text = "Geen onderwerpen gevonden"; article.Text = "Probeer bijvoorbeeld credentials, PostgreSQL, audit, veiligheid of backup."; }
    }
}
